node --input-type=module -e '
import ts from "typescript";
import path from "node:path";

const configPath = ts.findConfigFile(".", ts.sys.fileExists, "tsconfig.json");
if (!configPath) {
  console.error("NO_TSCONFIG");
  process.exit(1);
}
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, path.dirname(configPath));
const program = ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
const changed = [
  "e2e/display-screen-config.spec.ts",
  "src/features/display-management/CustomSelect.tsx",
  "src/features/display-management/DisplayManagementPage.tsx",
  "src/features/display-screen/DisplayScreenPage.tsx",
].map((file) => path.resolve(file));

for (const file of changed) {
  const sourceFile = program.getSourceFile(file);
  if (!sourceFile) {
    console.log("MISSING_SOURCE", file);
    continue;
  }
  const syntactic = program.getSyntacticDiagnostics(sourceFile);
  const semantic = program.getSemanticDiagnostics(sourceFile);
  const suggestion = program.getSuggestionDiagnostics(sourceFile);
  const print = (diag) => {
    const { line, character } = sourceFile.getLineAndCharacterOfPosition(diag.start ?? 0);
    const msg = ts.flattenDiagnosticMessageText(diag.messageText, "\n");
    return `${path.relative(".", file)}:${line + 1}:${character + 1} TS${diag.code} ${msg}`;
  };
  console.log("---", path.relative(".", file));
  console.log("syntactic", syntactic.length);
  syntactic.forEach((d) => console.log(print(d)));
  console.log("semantic", semantic.length);
  semantic.forEach((d) => console.log(print(d)));
  console.log("suggestion", suggestion.length);
  suggestion.forEach((d) => console.log(print(d)));
}
'
